from _lib import File
F=File('pre2020_yamaha450','o-y45','Yamaha YZ450F 2010-2017 by generation (2010-2013 reverse-cylinder, 2014-2017): what changed, dyno and weight, power character, tester settings, mapping, known problems and fixes (knowledge push 2026-11)','Yamaha',['YZ450F'],list(range(2010,2018)))
R=F.R; M='magazine'; C=['YZ450F']

# ---------------- 2010-2013
s=F.src(M,"Motocross Action - 2010 Yamaha YZ450F race test","https://motocrossactionmag.com/real-tests-2010-mxa-race-test-of-the-yamaha-yz450f","2009")
G=[2010,2011,2013]
R('identity','2010 redesign',C,G,"The 2010 YZ450F was the first with the rearward-tilted, reversed cylinder: intake at the front, exhaust out the back, fuel injection through a 44 mm throttle body, a four-valve head, a 97 x 60.8 mm bore and stroke (was 95 x 63.4), 12.5:1 compression and a new aluminium frame with 3 mm less fork offset and weight moved rearward. It gained 5.2 lb. This platform ran 2010-2013.",{'bore_stroke_mm':'97 x 60.8','compression':'12.5:1','throttle_body_mm':44,'cylinder':'tilted 8.2 degrees rearward'},'OEM',s)
R('power_feel','2010 dyno',C,[2010],"On a magazine dyno the 2010 YZ450F made 52.63 hp at 9,200 rpm and 33.02 lb-ft (2009 carburetted bike: 49.54 hp). It barks off the bottom, pulls hard through low and mid and holds on past the peak. It measured 96.4 dB.",{'peak_hp':52.63,'peak_rpm':9200,'peak_torque_lbft':33.02},'MEASURED',s,'high')
R('setups','2010-2013 tester settings',C,G,"A magazine test crew's setup for the 2010-2013 YZ450F stayed almost the same every year: fork stock 0.47 kg/mm springs, 355 cc oil, compression 10 clicks out (stock 13 in 2010-2012, 9 in 2013), rebound 9 out, legs flush. Shock 5.7 kg/mm spring, 100 mm sag, high-speed compression 1-1/2 turns out (stock 1-1/4), low-speed 7 clicks out (stock 8), rebound 11 out on 2010-2011 bikes (stock 14) and 14 out on 2012-2013 bikes (stock 17).",{'fork':'0.47 kg/mm, 355 cc, comp 10 out, reb 9 out, flush','shock':'5.7 kg/mm, sag 100 mm, HSC 1-1/2 turns, LSC 7 out, reb 11 out (2010-11) / 14 out (2012-13)'},'TUNER',s)
R('ecu_electronics','2010-2013 Power Tuner',C,G,"The 2010-2013 YZ450F is tuned with Yamaha's handheld GYTR Power Tuner (about $280), which needs no laptop or battery. It changes fuel (up to plus or minus 21%) and ignition timing at nine rpm and throttle points. It does not add peak power; testers used it to tame the bark off idle, richening the fuel and retarding the ignition down low. Faster riders went richest and most retarded; novices stayed closer to stock.",{'tool':'GYTR Power Tuner, 9 points, fuel +/-21%'},'TUNER',s)
s=F.src(M,"Motocross Action - 2011 Yamaha YZ450F test","https://motocrossactionmag.com/2011-yamaha-yz450f-motocross-test-the-most-revolutionary-motocross-bike-on-the-showroom-floor","2010")
R('identity','2011 changes',C,[2011],"The 2011 YZ450F is the 2010 bike with a revised clutch actuation arm (slightly heavier pull, steadier free play hot or cold) and white plastic. The engine is unchanged.",{},'OEM',s)
R('power_feel','2011 dyno',C,[2011],"On a magazine dyno the 2011 YZ450F made 53.88 hp and 33.95 lb-ft. Sharp hit off the bottom, strong middle, flat after about 8,000 rpm. It measured 94.5 dB.",{'peak_hp':53.88,'peak_torque_lbft':33.95},'MEASURED',s,'high')
R('setups','2010-2013 gearing',C,G,"The 2010-2012 YZ450F came with a 48-tooth rear sprocket and falls out of its power on the second-to-third shift; testers ran 13/49 or 13/50. The 2013 came with a 49 and testers went to 50.",{'stock':'48T (2010-2012), 49T (2013)','tested':'13/49 or 13/50'},'TUNER',s)
R('known_issues','2010-2013 weak points and fixes',C,G,"Repeated tester findings on the 2010-2013 YZ450F: the front end is loose and wiggles on corner entry and the rear rides high (a longer aftermarket shock link lowers the rear about 10 mm; raise the fork to keep it level; a radiator-lowering kit also helped front bite), the front brake is weak (a 270 mm disc kit), reaching the air filter means removing the seat and six bolts and lifting the tank (an aftermarket airbox kit fixes it), the textured shrouds go fuzzy and the bike is heavy at about 238 lb. One test bike cracked the swingarm chain-guide bracket. Stock 22 mm offset clamps worked best; no other offset tested better.",{'weight_lb':238,'stock_offset_mm':22},'TUNER',s)
s=F.src(M,"Motocross Action - 2012 Yamaha YZ450F test","https://motocrossactionmag.com/mxas-2012-yamaha-yz450f-motocross-test-the-muffler-corks-it-up-and-the-mapping-frees-it-up","2011")
R('identity','2012 changes',C,[2013],"For 2012 the YZ450F got a new fuel and ignition map, a muffler 42 mm longer with the core reduced from 33 to 30 mm, more low-to-mid fork compression damping, revised shock rebound and Dunlop MX51 tyres; the 2013 added only a white rear fender and black bars.",{'muffler_core_mm':30},'OEM',s,'medium','The 2012 YZ450F is not in the Garage roster; the 2013 carries all of the 2012 changes.')
s=F.src(M,"Motocross Action - 2013 Yamaha YZ450F test","https://motocrossactionmag.com/ten-years-ago-today-complete-test-of-the-2013-yamaha-yz450f","2012")
R('power_feel','2013 dyno and weight',C,[2013],"On a magazine dyno the 2013 YZ450F made 55.24 hp and weighed 238 lb. On the track it is a low-to-mid engine with an abrupt hit off the bottom. A 9 oz flywheel weight calmed it enough that pros went back to the stock map.",{'peak_hp':55.24,'weight_lb':238,'flywheel_weight_oz':9},'MEASURED',s,'high')

# ---------------- 2014-2017
s=F.src(M,"Motocross Action - 2014 Yamaha YZ450F test","https://motocrossactionmag.com/mxas-2014-yamaha-yz450f-motocross-test-when-yamaha-first-went-backwards-they-got-it-backwards-but-now-they-are-straightening-it-out","2013")
G=[2014,2015,2016,2017]
R('identity','2014 redesign',C,G,"The 2014 YZ450F kept the reversed cylinder in an all-new engine and chassis: wet sump, an exhaust that wraps around the cylinder, the airbox at the front under a cover, the fuel tank under the seat with a hidden filler, a lower third gear, clutch springs 10% stiffer, a 22 mm front axle (was 20) and stiffer springs at both ends (fork 4.9 N/mm, shock 58 N/mm). This platform ran 2014-2017.",{'fork_spring':'4.9 N/mm','shock_spring':'58 N/mm','front_axle_mm':22},'OEM',s)
R('power_feel','2014 dyno',C,[2014],"On a magazine dyno the 2014 YZ450F made 58.17 hp at 9,900 rpm, 2.25 hp more than the 2013 at peak and 3 hp more at 7,500 rpm; at 11,000 rpm it was still above the 2013's peak. The runs used the magazine's own richer map; on the stock map the engine was lean, stuttered off idle and coughed on landings.",{'peak_hp':58.17,'peak_rpm':9900},'MEASURED',s,'medium','Measured with a non-stock map.')
R('setups','2014 tester settings',C,[2014],"A magazine test crew's 2014 YZ450F setup: fork stock 4.9 N/mm springs, 335 cc oil (pros add 10 cc), compression 11 clicks out (stock 9), rebound 8 out, legs 4 mm up. Shock stock 58 N/mm spring, 105 mm sag (stock 100), high-speed compression 2 turns out (stock 1-1/2), low-speed 12 clicks out, rebound 9 out (stock 14). Rear sprocket 50 in place of 49.",{'fork':'335 cc, comp 11 out (stock 9), reb 8 out, 4 mm up','shock':'58 N/mm, sag 105 mm, HSC 2 turns, LSC 12 out, reb 9 out (stock 14)','gearing':'13/50 (stock 13/49)'},'TUNER',s)
R('ecu_electronics','2014 mapping',C,[2014],"The 2014 YZ450F's stock map is lean. With the GYTR Power Tuner, testers ran richer fuel and more ignition advance; with the stock pipe a slightly richer fuel map on stock timing also works, and aftermarket pipes want a little more fuel than stock. Yamaha's 2015 stock map is close to that corrected map, so a 2014 can be remapped to match.",{},'TUNER',s)
s=F.src(M,"Motocross Action - 2015 Yamaha YZ450F test","https://motocrossactionmag.com/2015-test-ride-yamaha-yz450f","2014")
R('identity','2015 changes',C,[2015],"2015 YZ450F changes: stiffer fork springs (5.0 N/mm) with new valving and 10 cc less oil, a remapped ECU, a throttle return spring 20% lighter, steel lower engine mounts in place of aluminium, a 48-tooth rear sprocket (was 49), a roller gear-stop lever, quarter-turn fasteners on the airbox cover, black rims and Dunlop MX52 tyres.",{'fork_spring':'5.0 N/mm','rear_sprocket':48},'OEM',s)
R('setups','2015-2017 tester settings',C,[2015,2016,2017],"A magazine test crew's 2015-2017 YZ450F setup: fork stock 5.0 N/mm springs, 315 cc oil, compression 10 clicks out (stock 8), rebound 8 out (stock 10), legs 4 mm up. Shock on the 2015: stock 58 N/mm spring, 105 mm sag; on the 2016-2017: 56 N/mm spring, 103 mm sag (stock 100); high-speed compression 2 turns out (stock 1-1/2), low-speed 12 clicks out, rebound 9 out (stock 14). Rear sprocket 49 in place of 48.",{'fork':'5.0 N/mm, 315 cc, comp 10 out (stock 8), reb 8 out (stock 10), 4 mm up','shock':'sag 105 mm (2015) / 103 mm (2016-17), HSC 2 turns, LSC 12 out, reb 9 out (stock 14)','gearing':'13/49 (stock 13/48)'},'TUNER',s)
s=F.src(M,"Motocross Action - 2016 Yamaha YZ450F race test","https://motocrossactionmag.com/2016-mxa-race-test-yamaha-yz450f","2015")
R('identity','2016 changes',C,[2016],"2016 YZ450F changes: a new exhaust cam (0.3 mm more lift, 8 degrees less duration, overlap cut from 80 to 68 degrees), stiffer valve springs, revised shift dogs and a stiffer gear-stop spring, launch control, fork offset changed from 22 mm to 25 mm, a softer 56 N/mm shock spring (was 58), wider swingarm pivot forgings, larger head stays, footpegs 5 mm lower and a 270 mm front disc (was 250).",{'offset_mm':25,'shock_spring':'56 N/mm','front_disc_mm':270,'cam_overlap_deg':68},'OEM',s)
R('power_feel','2015-2017 dyno and weight',C,[2015,2016,2017],"On a magazine dyno the 2016 and 2017 YZ450F made 56.85 hp at 9,800 rpm and the 2015 made 56.90; the 2016 cam added power and torque from 5,000 to 6,500 rpm and matched the 2015 above that. Weight was 238 lb without fuel, 11 lb more than the 2016 450 SX-F and 16 lb more than the 2017. Strong off the line and through the middle with a hard surge past about 9,000 rpm.",{'peak_hp':56.85,'peak_rpm':9800,'weight_lb':238},'MEASURED',s,'high','An earlier test by the same magazine quoted about 59 hp for the 2015; the 56.9 figure is from its later back-to-back comparison.')
R('ecu_electronics','2016-2017 launch control and mapping',C,[2016,2017],"Launch control on the 2016-2017 YZ450F cuts power from 4,500 rpm at 30% throttle and gives it back after 30-60 ft or at the shift to third. The stock map gave the best all-round power in testing. With the Power Tuner, more ignition advance and slightly richer fuel up high sharpens it; for a mellower bike richen every fuel cell and retard every ignition cell at least 2 degrees. A flywheel weight also calms the corner-exit wheelie.",{'launch_control':'cuts from 4,500 rpm at 30% throttle; off after 30-60 ft or in 3rd'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2017 Yamaha YZ450F race test","https://motocrossactionmag.com/mxa-race-test-2017-yamaha-yz450f","2016")
R('identity','2017 changes',C,[2017],"The 2017 YZ450F is the 2016 bike with recessed fastener holes on the tank cover, a better countershaft seal, an updated oil strainer, a rear disc less prone to warping and Dunlop MX3S tyres.",{},'OEM',s2)
R('known_issues','2014-2017 weak points and fixes',C,G,"Repeated tester findings on the 2014-2017 YZ450F: vague, loose turn-in and a tall rear (raise the fork 4 mm, run 103-105 mm sag, fit a 143.5 mm aftermarket shock link, which drops the rear about 8 mm, and swap the stock front tyre for one suited to the dirt), a wide gap in the gearbox on the second-to-third shift (one tooth more on the rear), the quarter-turn airbox fasteners falling out or snagging on 2015-2016 bikes (tape them or go back to bolts), a grip that wears the rider's thumb raw (a grip donut), loud intake noise from the front airbox, brakes behind the class best and an exhaust that is very hard to remove (a long extension and a swivel 10 mm socket).",{'link_mm':143.5},'TUNER',s2)
R('chassis','2014-2017 handling character',C,G,"The 2014-2017 YZ450F is stable and has the best stock suspension of its era, but the front feels heavy and wide and hunts on turn entry while the rear sits tall. The 2016 change to 25 mm offset and a softer shock spring helped without curing it. Reliability and the cable clutch were consistently praised.",{},'TUNER',s2)

if __name__=='__main__': F.write()
